  mixins: [NotifyMixin],
  handleClick: function () {
    this.notify('hello');
  },
  render: function () {
    return <button onClick={this.handleClick}>click me!</button>
  }
});
```

And bury it inside your app:

```jsx
var MyApp = React.createClass({
  render: function () {
    return {
      <div>
        <div>
          <MyComp />
        </div>
      </div>
    }
  }
});
