	, adapter = new Hyperion(db);

adapter.insertNode(1701, 'Spaceship', {
		brand: 'Starfleet'
	}).catch(function(err) {
		console.log(err);
	});

adapter.updateNode(1701, 'Spaceship', {
		destroyed: 12
	}).catch(function(err) {
		console.log(err);
	});
```

